-- ADC 牙科诊所逻辑数据库基线（PostgreSQL 18）
-- 本文件由数据字典生成，需结合实际部署环境补充 ID 生成策略和迁移版本。
-- 不包含退款、工资、成本、利润、奖金支付或保险理赔模块。
SET TIME ZONE 'Asia/Shanghai';

CREATE TABLE "PATIENT" (
  "patient_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "master_no" VARCHAR(255) NOT NULL,
  "name" VARCHAR(255) NOT NULL,
  "birth_date" DATE NULL,
  "address" VARCHAR(255) NULL,
  "phone" VARCHAR(255) NOT NULL,
  "email" VARCHAR(255) NULL,
  "emergency_name" VARCHAR(255) NULL,
  "emergency_phone" VARCHAR(255) NULL,
  "special_needs" VARCHAR(255) NULL,
  "allergy_assessment" VARCHAR(30) NOT NULL,
  "merged_into_patient_id" BIGINT NULL,
  PRIMARY KEY ("patient_id"),
  CONSTRAINT "uq_patient_1" UNIQUE ("master_no"),
  CONSTRAINT "ck_patient_allergy_assessment" CHECK ("allergy_assessment" IN ('UNKNOWN', 'NONE_KNOWN', 'RECORDED'))
);

CREATE TABLE "ALLERGEN" (
  "allergen_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" VARCHAR(255) NOT NULL,
  PRIMARY KEY ("allergen_id"),
  CONSTRAINT "uq_allergen_1" UNIQUE ("name")
);

CREATE TABLE "PATIENT_ALLERGY" (
  "patient_id" BIGINT NOT NULL,
  "allergen_id" BIGINT NOT NULL,
  "reaction" VARCHAR(255) NOT NULL,
  "notes" VARCHAR(255) NULL,
  "recorded_at" TIMESTAMP WITH TIME ZONE NOT NULL,
  PRIMARY KEY ("patient_id", "allergen_id")
);

CREATE TABLE "STAFF" (
  "staff_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "staff_no" VARCHAR(255) NOT NULL,
  "name" VARCHAR(255) NOT NULL,
  "phone" VARCHAR(255) NULL,
  "active" BOOLEAN NOT NULL,
  PRIMARY KEY ("staff_id"),
  CONSTRAINT "uq_staff_1" UNIQUE ("staff_no")
);

CREATE TABLE "CLINIC" (
  "clinic_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "clinic_code" VARCHAR(255) NOT NULL,
  "name" VARCHAR(255) NOT NULL,
  "address" VARCHAR(255) NOT NULL,
  "latitude" DECIMAL(8,2) NULL,
  "longitude" DECIMAL(8,2) NULL,
  "phone" VARCHAR(255) NOT NULL,
  "email" VARCHAR(255) NULL,
  "manager_staff_id" BIGINT NULL,
  PRIMARY KEY ("clinic_id"),
  CONSTRAINT "uq_clinic_1" UNIQUE ("clinic_code")
);

CREATE TABLE "DENTIST" (
  "dentist_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "license_no" VARCHAR(255) NOT NULL,
  PRIMARY KEY ("dentist_id"),
  CONSTRAINT "uq_dentist_1" UNIQUE ("license_no")
);

CREATE TABLE "PRACTICE" (
  "practice_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "dentist_id" BIGINT NOT NULL,
  "clinic_id" BIGINT NOT NULL,
  "valid_from" DATE NOT NULL,
  "valid_to" DATE NULL,
  "status" VARCHAR(30) NOT NULL,
  PRIMARY KEY ("practice_id"),
  CONSTRAINT "uq_practice_1" UNIQUE ("dentist_id", "clinic_id", "valid_from"),
  CONSTRAINT "ck_practice_status" CHECK ("status" IN ('ACTIVE', 'SUSPENDED', 'ENDED'))
);

CREATE TABLE "QUALIFICATION" (
  "qualification_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "code" VARCHAR(255) NOT NULL,
  "name" VARCHAR(255) NOT NULL,
  PRIMARY KEY ("qualification_id"),
  CONSTRAINT "uq_qualification_1" UNIQUE ("code")
);

CREATE TABLE "DENTIST_QUALIFICATION" (
  "dentist_qualification_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "dentist_id" BIGINT NOT NULL,
  "qualification_id" BIGINT NOT NULL,
  "certificate_no" VARCHAR(255) NOT NULL,
  "valid_from" DATE NOT NULL,
  "valid_to" DATE NOT NULL,
  PRIMARY KEY ("dentist_qualification_id"),
  CONSTRAINT "uq_dentist_qualification_1" UNIQUE ("dentist_id", "qualification_id", "certificate_no")
);

CREATE TABLE "TREATMENT_ITEM" (
  "treatment_item_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "item_code" VARCHAR(255) NOT NULL,
  "name" VARCHAR(255) NOT NULL,
  "standard_unit" VARCHAR(255) NOT NULL,
  "active" BOOLEAN NOT NULL,
  PRIMARY KEY ("treatment_item_id"),
  CONSTRAINT "uq_treatment_item_1" UNIQUE ("item_code")
);

CREATE TABLE "TREATMENT_REQUIRED_QUALIFICATION" (
  "treatment_item_id" BIGINT NOT NULL,
  "qualification_id" BIGINT NOT NULL,
  PRIMARY KEY ("treatment_item_id", "qualification_id")
);

CREATE TABLE "SHIFT" (
  "shift_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "shift_series_no" VARCHAR(255) NOT NULL,
  "dentist_id" BIGINT NOT NULL,
  "clinic_id" BIGINT NOT NULL,
  "starts_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  "ends_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  "status" VARCHAR(30) NOT NULL,
  "version_no" INT NOT NULL,
  "previous_shift_id" BIGINT NULL,
  "published_by_staff_id" BIGINT NULL,
  "published_at" TIMESTAMP WITH TIME ZONE NULL,
  PRIMARY KEY ("shift_id"),
  CONSTRAINT "uq_shift_1" UNIQUE ("shift_series_no", "version_no"),
  CONSTRAINT "ck_shift_status" CHECK ("status" IN ('DRAFT', 'PUBLISHED', 'SUPERSEDED', 'CANCELLED')),
  CONSTRAINT "ck_shift_rule_1" CHECK ("ends_at" > "starts_at")
);

CREATE TABLE "APPOINTMENT" (
  "appointment_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "patient_id" BIGINT NOT NULL,
  "shift_id" BIGINT NOT NULL,
  "starts_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  "ends_at" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  "status" VARCHAR(30) NOT NULL,
  "created_by_account_id" BIGINT NOT NULL,
  "created_at" TIMESTAMP WITH TIME ZONE NOT NULL,
  PRIMARY KEY ("appointment_id"),
  CONSTRAINT "ck_appointment_status" CHECK ("status" IN ('BOOKED', 'CONFIRMED', 'CANCELLED', 'ARRIVED', 'NO_SHOW', 'COMPLETED')),
  CONSTRAINT "ck_appointment_rule_1" CHECK ("ends_at" > "starts_at")
);

CREATE TABLE "APPOINTMENT_REQUEST_ITEM" (
  "appointment_id" BIGINT NOT NULL,
  "treatment_item_id" BIGINT NOT NULL,
  PRIMARY KEY ("appointment_id", "treatment_item_id")
);

CREATE TABLE "APPOINTMENT_EVENT" (
  "event_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "appointment_id" BIGINT NOT NULL,
  "old_status" VARCHAR(30) NULL,
  "new_status" VARCHAR(30) NOT NULL,
  "old_shift_id" BIGINT NULL,
  "new_shift_id" BIGINT NULL,
  "old_starts_at" TIMESTAMP WITHOUT TIME ZONE NULL,
  "old_ends_at" TIMESTAMP WITHOUT TIME ZONE NULL,
  "new_starts_at" TIMESTAMP WITHOUT TIME ZONE NULL,
  "new_ends_at" TIMESTAMP WITHOUT TIME ZONE NULL,
  "reason" VARCHAR(255) NULL,
  "operator_account_id" BIGINT NOT NULL,
  "occurred_at" TIMESTAMP WITH TIME ZONE NOT NULL,
  PRIMARY KEY ("event_id"),
  CONSTRAINT "ck_appointment_event_old_status" CHECK ("old_status" IN ('BOOKED', 'CONFIRMED', 'CANCELLED', 'ARRIVED', 'NO_SHOW', 'COMPLETED')),
  CONSTRAINT "ck_appointment_event_new_status" CHECK ("new_status" IN ('BOOKED', 'CONFIRMED', 'CANCELLED', 'ARRIVED', 'NO_SHOW', 'COMPLETED'))
);

CREATE TABLE "ENCOUNTER" (
  "encounter_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "appointment_id" BIGINT NOT NULL,
  "chief_complaint" VARCHAR(255) NULL,
  "diagnosis" VARCHAR(255) NULL,
  "special_needs" VARCHAR(255) NULL,
  "status" VARCHAR(30) NOT NULL,
  "arrived_at" TIMESTAMP WITH TIME ZONE NOT NULL,
  "arrived_by_account_id" BIGINT NOT NULL,
  "completed_at" TIMESTAMP WITH TIME ZONE NULL,
  "confirmed_by_dentist_id" BIGINT NULL,
  PRIMARY KEY ("encounter_id"),
  CONSTRAINT "uq_encounter_1" UNIQUE ("appointment_id"),
  CONSTRAINT "ck_encounter_status" CHECK ("status" IN ('ARRIVED', 'IN_PROGRESS', 'COMPLETED', 'VOID'))
);

CREATE TABLE "PRICE_VERSION" (
  "price_version_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "treatment_item_id" BIGINT NOT NULL,
  "version_no" INT NOT NULL,
  "unit" VARCHAR(255) NOT NULL,
  "unit_price" DECIMAL(12,2) NOT NULL,
  "currency" VARCHAR(255) NOT NULL,
  "valid_from" DATE NOT NULL,
  "valid_to" DATE NULL,
  PRIMARY KEY ("price_version_id"),
  CONSTRAINT "uq_price_version_1" UNIQUE ("treatment_item_id", "version_no"),
  CONSTRAINT "uq_price_version_2" UNIQUE ("price_version_id", "treatment_item_id"),
  CONSTRAINT "ck_price_version_rule_1" CHECK ("unit_price" >= 0),
  CONSTRAINT "ck_price_version_rule_2" CHECK ("valid_to" IS NULL OR "valid_to" > "valid_from")
);

CREATE TABLE "TREATMENT_LINE" (
  "treatment_line_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "encounter_id" BIGINT NOT NULL,
  "treatment_item_id" BIGINT NOT NULL,
  "price_version_id" BIGINT NOT NULL,
  "quantity" DECIMAL(12,3) NOT NULL,
  "name_snapshot" VARCHAR(255) NOT NULL,
  "unit_snapshot" VARCHAR(255) NOT NULL,
  "unit_price_snapshot" DECIMAL(12,2) NOT NULL,
  "notes" VARCHAR(255) NULL,
  "confirmed_at" TIMESTAMP WITH TIME ZONE NULL,
  PRIMARY KEY ("treatment_line_id"),
  CONSTRAINT "ck_treatment_line_rule_1" CHECK ("quantity" > 0),
  CONSTRAINT "ck_treatment_line_rule_2" CHECK ("unit_price_snapshot" >= 0)
);

CREATE TABLE "INVOICE" (
  "invoice_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "encounter_id" BIGINT NOT NULL,
  "invoice_no" VARCHAR(255) NOT NULL,
  "status" VARCHAR(30) NOT NULL,
  PRIMARY KEY ("invoice_id"),
  CONSTRAINT "uq_invoice_1" UNIQUE ("encounter_id"),
  CONSTRAINT "uq_invoice_2" UNIQUE ("invoice_no"),
  CONSTRAINT "ck_invoice_status" CHECK ("status" IN ('DRAFT', 'CONFIRMED', 'VOID', 'PAID'))
);

CREATE TABLE "INVOICE_VERSION" (
  "invoice_version_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "invoice_id" BIGINT NOT NULL,
  "version_no" INT NOT NULL,
  "total_amount" DECIMAL(12,2) NOT NULL,
  "currency" VARCHAR(255) NOT NULL,
  "issued_at" TIMESTAMP WITH TIME ZONE NOT NULL,
  "issued_by_account_id" BIGINT NOT NULL,
  "correction_reason" VARCHAR(255) NULL,
  PRIMARY KEY ("invoice_version_id"),
  CONSTRAINT "uq_invoice_version_1" UNIQUE ("invoice_id", "version_no")
);

CREATE TABLE "INVOICE_LINE" (
  "invoice_line_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "invoice_version_id" BIGINT NOT NULL,
  "treatment_line_id" BIGINT NOT NULL,
  "description_snapshot" VARCHAR(255) NOT NULL,
  "unit_snapshot" VARCHAR(255) NOT NULL,
  "quantity_snapshot" DECIMAL(12,3) NOT NULL,
  "unit_price_snapshot" DECIMAL(12,2) NOT NULL,
  "line_total" DECIMAL(12,2) NOT NULL,
  PRIMARY KEY ("invoice_line_id"),
  CONSTRAINT "uq_invoice_line_1" UNIQUE ("invoice_version_id", "treatment_line_id"),
  CONSTRAINT "ck_invoice_line_rule_1" CHECK ("quantity_snapshot" > 0),
  CONSTRAINT "ck_invoice_line_rule_2" CHECK ("unit_price_snapshot" >= 0),
  CONSTRAINT "ck_invoice_line_rule_3" CHECK ("line_total" >= 0)
);

CREATE TABLE "PAYMENT" (
  "payment_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "invoice_version_id" BIGINT NOT NULL,
  "request_no" VARCHAR(255) NOT NULL,
  "receipt_no" VARCHAR(255) NULL,
  "amount" DECIMAL(12,2) NOT NULL,
  "method" VARCHAR(30) NOT NULL,
  "status" VARCHAR(30) NOT NULL,
  "paid_at" TIMESTAMP WITH TIME ZONE NOT NULL,
  "operator_account_id" BIGINT NOT NULL,
  PRIMARY KEY ("payment_id"),
  CONSTRAINT "uq_payment_1" UNIQUE ("request_no"),
  CONSTRAINT "uq_payment_2" UNIQUE ("receipt_no"),
  CONSTRAINT "ck_payment_method" CHECK ("method" IN ('CASH', 'BANK_CARD', 'MOBILE_PAYMENT')),
  CONSTRAINT "ck_payment_status" CHECK ("status" IN ('SUCCESS', 'PENDING', 'FAILED')),
  CONSTRAINT "ck_payment_rule_1" CHECK ("amount" > 0)
);

CREATE TABLE "SHIFT_REQUEST" (
  "request_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "applicant_dentist_id" BIGINT NOT NULL,
  "request_type" VARCHAR(30) NOT NULL,
  "requested_from" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  "requested_to" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  "reason" VARCHAR(255) NOT NULL,
  "status" VARCHAR(30) NOT NULL,
  "submitted_at" TIMESTAMP WITH TIME ZONE NOT NULL,
  "reviewer_staff_id" BIGINT NULL,
  "reviewed_at" TIMESTAMP WITH TIME ZONE NULL,
  "rejection_reason" VARCHAR(255) NULL,
  PRIMARY KEY ("request_id"),
  CONSTRAINT "ck_shift_request_request_type" CHECK ("request_type" IN ('SHIFT_CHANGE', 'LEAVE', 'OTHER')),
  CONSTRAINT "ck_shift_request_status" CHECK ("status" IN ('SUBMITTED', 'REJECTED', 'COORDINATING', 'IMPLEMENTED'))
);

CREATE TABLE "SHIFT_REQUEST_ITEM" (
  "request_id" BIGINT NOT NULL,
  "shift_id" BIGINT NOT NULL,
  "proposed_dentist_id" BIGINT NULL,
  "proposed_clinic_id" BIGINT NULL,
  "proposed_starts_at" TIMESTAMP WITHOUT TIME ZONE NULL,
  "proposed_ends_at" TIMESTAMP WITHOUT TIME ZONE NULL,
  "result_shift_id" BIGINT NULL,
  PRIMARY KEY ("request_id", "shift_id")
);

CREATE TABLE "REQUEST_APPOINTMENT_IMPACT" (
  "request_id" BIGINT NOT NULL,
  "appointment_id" BIGINT NOT NULL,
  "resolution_status" VARCHAR(30) NOT NULL,
  "resolution_event_id" BIGINT NULL,
  "resolved_by_account_id" BIGINT NULL,
  "resolved_at" TIMESTAMP WITH TIME ZONE NULL,
  PRIMARY KEY ("request_id", "appointment_id"),
  CONSTRAINT "ck_request_appointment_impact_resolution_status" CHECK ("resolution_status" IN ('PENDING', 'CONTACTED', 'CONFIRMED', 'RESOLVED'))
);

CREATE TABLE "MATERIAL" (
  "material_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "material_code" VARCHAR(255) NOT NULL,
  "name" VARCHAR(255) NOT NULL,
  "unit" VARCHAR(255) NOT NULL,
  "active" BOOLEAN NOT NULL,
  PRIMARY KEY ("material_id"),
  CONSTRAINT "uq_material_1" UNIQUE ("material_code")
);

CREATE TABLE "CLINIC_STOCK" (
  "clinic_id" BIGINT NOT NULL,
  "material_id" BIGINT NOT NULL,
  "on_hand" DECIMAL(12,3) NOT NULL,
  "warning_threshold" DECIMAL(12,3) NOT NULL,
  "lock_version" INT NOT NULL,
  PRIMARY KEY ("clinic_id", "material_id"),
  CONSTRAINT "ck_clinic_stock_rule_1" CHECK ("on_hand" >= 0),
  CONSTRAINT "ck_clinic_stock_rule_2" CHECK ("warning_threshold" >= 0)
);

CREATE TABLE "TREATMENT_MATERIAL_USAGE" (
  "usage_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "treatment_line_id" BIGINT NOT NULL,
  "clinic_id" BIGINT NOT NULL,
  "material_id" BIGINT NOT NULL,
  "request_no" VARCHAR(255) NOT NULL,
  "quantity" DECIMAL(12,3) NOT NULL,
  "recorded_at" TIMESTAMP WITH TIME ZONE NOT NULL,
  PRIMARY KEY ("usage_id"),
  CONSTRAINT "uq_treatment_material_usage_1" UNIQUE ("request_no"),
  CONSTRAINT "ck_treatment_material_usage_rule_1" CHECK ("quantity" > 0)
);

CREATE TABLE "STOCK_MOVEMENT" (
  "movement_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "clinic_id" BIGINT NOT NULL,
  "material_id" BIGINT NOT NULL,
  "usage_id" BIGINT NULL,
  "movement_type" VARCHAR(30) NOT NULL,
  "quantity_delta" DECIMAL(12,3) NOT NULL,
  "reason" VARCHAR(255) NOT NULL,
  "occurred_at" TIMESTAMP WITH TIME ZONE NOT NULL,
  "operator_account_id" BIGINT NOT NULL,
  PRIMARY KEY ("movement_id"),
  CONSTRAINT "uq_stock_movement_1" UNIQUE ("usage_id"),
  CONSTRAINT "ck_stock_movement_movement_type" CHECK ("movement_type" IN ('INBOUND', 'USAGE', 'ADJUSTMENT'))
);

CREATE TABLE "ACCOUNT" (
  "account_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "login_name" VARCHAR(255) NOT NULL,
  "patient_id" BIGINT NULL,
  "staff_id" BIGINT NULL,
  "active" BOOLEAN NOT NULL,
  PRIMARY KEY ("account_id"),
  CONSTRAINT "uq_account_1" UNIQUE ("login_name"),
  CONSTRAINT "uq_account_2" UNIQUE ("patient_id"),
  CONSTRAINT "uq_account_3" UNIQUE ("staff_id")
);

CREATE TABLE "ACCESS_GRANT" (
  "grant_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "account_id" BIGINT NOT NULL,
  "role_code" VARCHAR(30) NOT NULL,
  "scope_type" VARCHAR(30) NOT NULL,
  "clinic_id" BIGINT NULL,
  PRIMARY KEY ("grant_id"),
  CONSTRAINT "ck_access_grant_role_code" CHECK ("role_code" IN ('PATIENT', 'RECEPTION', 'DENTIST', 'CLINIC_MANAGER', 'HQ_MANAGER')),
  CONSTRAINT "ck_access_grant_scope_type" CHECK ("scope_type" IN ('SELF', 'CLINIC', 'CHAIN'))
);

CREATE TABLE "AUDIT_EVENT" (
  "audit_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "actor_account_id" BIGINT NOT NULL,
  "object_type" VARCHAR(255) NOT NULL,
  "object_key" VARCHAR(255) NOT NULL,
  "action" VARCHAR(255) NOT NULL,
  "reason" VARCHAR(255) NULL,
  "before_value" JSONB NULL,
  "after_value" JSONB NULL,
  "occurred_at" TIMESTAMP WITH TIME ZONE NOT NULL,
  PRIMARY KEY ("audit_id")
);

CREATE TABLE "DENTIST_PERFORMANCE" (
  "performance_id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "dentist_id" BIGINT NOT NULL,
  "clinic_id" BIGINT NOT NULL,
  "period_start" DATE NOT NULL,
  "period_end" DATE NOT NULL,
  "appointment_count" INT NOT NULL,
  "attended_count" INT NOT NULL,
  "cancelled_count" INT NOT NULL,
  "no_show_count" INT NOT NULL,
  "completed_count" INT NOT NULL,
  "treatment_count" INT NOT NULL,
  "workload_target_count" INT NOT NULL,
  "performance_score" DECIMAL(8,2) NULL,
  "reward_level" VARCHAR(30) NOT NULL,
  "review_status" VARCHAR(30) NOT NULL,
  "reviewed_by_account_id" BIGINT NULL,
  "reviewed_at" TIMESTAMP WITH TIME ZONE NULL,
  "calculation_version" VARCHAR(255) NOT NULL,
  "calculated_at" TIMESTAMP WITH TIME ZONE NOT NULL,
  "created_at" TIMESTAMP WITH TIME ZONE NOT NULL,
  PRIMARY KEY ("performance_id"),
  CONSTRAINT "uq_dentist_performance_1" UNIQUE ("dentist_id", "clinic_id", "period_start", "period_end", "calculation_version"),
  CONSTRAINT "ck_dentist_performance_reward_level" CHECK ("reward_level" IN ('NONE', 'NORMAL', 'GOOD', 'EXCELLENT')),
  CONSTRAINT "ck_dentist_performance_review_status" CHECK ("review_status" IN ('DRAFT', 'CONFIRMED', 'ARCHIVED')),
  CONSTRAINT "ck_dentist_performance_rule_1" CHECK ("period_end" > "period_start"),
  CONSTRAINT "ck_dentist_performance_rule_2" CHECK ("appointment_count" >= 0 AND "attended_count" >= 0 AND "cancelled_count" >= 0 AND "no_show_count" >= 0 AND "completed_count" >= 0 AND "treatment_count" >= 0),
  CONSTRAINT "ck_dentist_performance_rule_3" CHECK ("attended_count" + "cancelled_count" + "no_show_count" <= "appointment_count" AND "completed_count" <= "attended_count"),
  CONSTRAINT "ck_dentist_performance_rule_4" CHECK ("workload_target_count" >= 0),
  CONSTRAINT "ck_dentist_performance_rule_5" CHECK ("performance_score" IS NULL OR ("performance_score" >= 0 AND "performance_score" <= 100))
);

-- 外键统一在父表创建完成后添加。
ALTER TABLE "PATIENT" ADD CONSTRAINT "fk_patient_patient_1" FOREIGN KEY ("merged_into_patient_id") REFERENCES "PATIENT" ("patient_id");
ALTER TABLE "PATIENT_ALLERGY" ADD CONSTRAINT "fk_patient_allergy_patient_2" FOREIGN KEY ("patient_id") REFERENCES "PATIENT" ("patient_id");
ALTER TABLE "PATIENT_ALLERGY" ADD CONSTRAINT "fk_patient_allergy_allergen_3" FOREIGN KEY ("allergen_id") REFERENCES "ALLERGEN" ("allergen_id");
ALTER TABLE "CLINIC" ADD CONSTRAINT "fk_clinic_staff_4" FOREIGN KEY ("manager_staff_id") REFERENCES "STAFF" ("staff_id");
ALTER TABLE "DENTIST" ADD CONSTRAINT "fk_dentist_staff_5" FOREIGN KEY ("dentist_id") REFERENCES "STAFF" ("staff_id");
ALTER TABLE "PRACTICE" ADD CONSTRAINT "fk_practice_dentist_6" FOREIGN KEY ("dentist_id") REFERENCES "DENTIST" ("dentist_id");
ALTER TABLE "PRACTICE" ADD CONSTRAINT "fk_practice_clinic_7" FOREIGN KEY ("clinic_id") REFERENCES "CLINIC" ("clinic_id");
ALTER TABLE "DENTIST_QUALIFICATION" ADD CONSTRAINT "fk_dentist_qualification_dentist_8" FOREIGN KEY ("dentist_id") REFERENCES "DENTIST" ("dentist_id");
ALTER TABLE "DENTIST_QUALIFICATION" ADD CONSTRAINT "fk_dentist_qualification_qualification_9" FOREIGN KEY ("qualification_id") REFERENCES "QUALIFICATION" ("qualification_id");
ALTER TABLE "TREATMENT_REQUIRED_QUALIFICATION" ADD CONSTRAINT "fk_treatment_required_qualification_treatment_item_10" FOREIGN KEY ("treatment_item_id") REFERENCES "TREATMENT_ITEM" ("treatment_item_id");
ALTER TABLE "TREATMENT_REQUIRED_QUALIFICATION" ADD CONSTRAINT "fk_treatment_required_qualification_qualification_11" FOREIGN KEY ("qualification_id") REFERENCES "QUALIFICATION" ("qualification_id");
ALTER TABLE "SHIFT" ADD CONSTRAINT "fk_shift_dentist_12" FOREIGN KEY ("dentist_id") REFERENCES "DENTIST" ("dentist_id");
ALTER TABLE "SHIFT" ADD CONSTRAINT "fk_shift_clinic_13" FOREIGN KEY ("clinic_id") REFERENCES "CLINIC" ("clinic_id");
ALTER TABLE "SHIFT" ADD CONSTRAINT "fk_shift_shift_14" FOREIGN KEY ("previous_shift_id") REFERENCES "SHIFT" ("shift_id");
ALTER TABLE "SHIFT" ADD CONSTRAINT "fk_shift_staff_15" FOREIGN KEY ("published_by_staff_id") REFERENCES "STAFF" ("staff_id");
ALTER TABLE "APPOINTMENT" ADD CONSTRAINT "fk_appointment_patient_16" FOREIGN KEY ("patient_id") REFERENCES "PATIENT" ("patient_id");
ALTER TABLE "APPOINTMENT" ADD CONSTRAINT "fk_appointment_shift_17" FOREIGN KEY ("shift_id") REFERENCES "SHIFT" ("shift_id");
ALTER TABLE "APPOINTMENT" ADD CONSTRAINT "fk_appointment_account_18" FOREIGN KEY ("created_by_account_id") REFERENCES "ACCOUNT" ("account_id");
ALTER TABLE "APPOINTMENT_REQUEST_ITEM" ADD CONSTRAINT "fk_appointment_request_item_appointment_19" FOREIGN KEY ("appointment_id") REFERENCES "APPOINTMENT" ("appointment_id");
ALTER TABLE "APPOINTMENT_REQUEST_ITEM" ADD CONSTRAINT "fk_appointment_request_item_treatment_item_20" FOREIGN KEY ("treatment_item_id") REFERENCES "TREATMENT_ITEM" ("treatment_item_id");
ALTER TABLE "APPOINTMENT_EVENT" ADD CONSTRAINT "fk_appointment_event_appointment_21" FOREIGN KEY ("appointment_id") REFERENCES "APPOINTMENT" ("appointment_id");
ALTER TABLE "APPOINTMENT_EVENT" ADD CONSTRAINT "fk_appointment_event_shift_22" FOREIGN KEY ("old_shift_id") REFERENCES "SHIFT" ("shift_id");
ALTER TABLE "APPOINTMENT_EVENT" ADD CONSTRAINT "fk_appointment_event_shift_23" FOREIGN KEY ("new_shift_id") REFERENCES "SHIFT" ("shift_id");
